extends RefCounted

const QUAR_BASE := "E:/ghost-company-quarantine"

func _abs(p: String) -> String:
	return ProjectSettings.globalize_path(p)

func _mkdir_abs(p: String) -> void:
	if p != "" and not DirAccess.dir_exists_absolute(p):
		DirAccess.make_dir_recursive_absolute(p)

func run(ops_path: String) -> String:
	var f := FileAccess.open(ops_path, FileAccess.READ)
	if f == null:
		return JSON.stringify({"ok": false, "error": "cannot open " + ops_path})
	var ops = JSON.parse_string(f.get_as_text())
	var rep := {"quarantined": [], "moved": [], "deleted": [], "errors": []}
	for src in ops.get("quarantine", []):
		var a := _abs(String(src))
		var q := QUAR_BASE + "/" + String(src).substr(6)
		if not (DirAccess.dir_exists_absolute(a) or FileAccess.file_exists(a)):
			rep["errors"].append({"op": "quarantine", "src": src, "error": "missing"})
			continue
		_mkdir_abs(q.get_base_dir())
		var err := DirAccess.rename_absolute(a, q)
		if err == OK:
			rep["quarantined"].append(String(src))
			if FileAccess.file_exists(a + ".import"):
				DirAccess.remove_absolute(a + ".import")
		else:
			rep["errors"].append({"op": "quarantine", "src": src, "error": error_string(err)})
	for m in ops.get("move", []):
		var a := _abs(String(m["from"]))
		var b := _abs(String(m["to"]))
		if not (DirAccess.dir_exists_absolute(a) or FileAccess.file_exists(a)):
			rep["errors"].append({"op": "move", "src": m["from"], "error": "missing"})
			continue
		_mkdir_abs(b.get_base_dir())
		var err2 := DirAccess.rename_absolute(a, b)
		if err2 == OK:
			rep["moved"].append(String(m["from"]) + " -> " + String(m["to"]))
			if FileAccess.file_exists(a + ".import"):
				DirAccess.rename_absolute(a + ".import", b + ".import")
		else:
			rep["errors"].append({"op": "move", "src": m["from"], "error": error_string(err2)})
	for src in ops.get("delete", []):
		var a := _abs(String(src))
		if DirAccess.dir_exists_absolute(a):
			var d := DirAccess.open(a.get_base_dir())
			var err3 := d.remove_recursive(a.get_file())
			if err3 == OK:
				rep["deleted"].append(String(src))
			else:
				rep["errors"].append({"op": "delete", "src": src, "error": error_string(err3)})
		elif FileAccess.file_exists(a):
			DirAccess.remove_absolute(a)
			if FileAccess.file_exists(a + ".import"):
				DirAccess.remove_absolute(a + ".import")
			rep["deleted"].append(String(src))
		else:
			rep["errors"].append({"op": "delete", "src": src, "error": "missing"})
	return JSON.stringify(rep)
